function maxProductPath(grid) {
  const MOD = 1000000007;
  const rows = grid.length;
  const cols = grid[0].length;
  const high = Array.from({ length: rows }, () => new Array(cols).fill(0));
  const low = Array.from({ length: rows }, () => new Array(cols).fill(0));
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const value = grid[r][c];
      if (r === 0 && c === 0) {
        high[r][c] = value;
        low[r][c] = value;
        continue;
      }
      let bestBefore = -Infinity;
      let worstBefore = Infinity;
      if (r > 0) {
        bestBefore = Math.max(bestBefore, high[r - 1][c]);
        worstBefore = Math.min(worstBefore, low[r - 1][c]);
      }
      if (c > 0) {
        bestBefore = Math.max(bestBefore, high[r][c - 1]);
        worstBefore = Math.min(worstBefore, low[r][c - 1]);
      }
      if (value === 0) {
        high[r][c] = 0;
        low[r][c] = 0;
      } else if (value > 0) {
        high[r][c] = bestBefore * value;
        low[r][c] = worstBefore * value;
      } else {
        high[r][c] = worstBefore * value;
        low[r][c] = bestBefore * value;
      }
    }
  }
  const best = high[rows - 1][cols - 1];
  if (best < 0) {
    return -1;
  }
  return best % MOD;
}

