function maxProductPath(grid) {
  // Keep every exact product (BigInt) that some route can have at each cell, then take the largest at the end.
  const rows = grid.length, cols = grid[0].length;
  const reach = grid.map(row => row.map(() => new Set()));
  reach[0][0].add(BigInt(grid[0][0]));
  for (let r = 0; r < rows; r++)
    for (let c = 0; c < cols; c++) {
      const factor = BigInt(grid[r][c]);
      const from = [];
      if (r > 0) from.push(reach[r - 1][c]);
      if (c > 0) from.push(reach[r][c - 1]);
      for (const set of from) for (const product of set) reach[r][c].add(product * factor);
    }
  let best = null;
  for (const product of reach[rows - 1][cols - 1]) if (best === null || product > best) best = product;
  return best < 0n ? -1 : Number(best % 1000000007n);
}

