function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const rows = large ? int(12, 15) : int(1, 5);
  const cols = large ? int(12, 15) : int(1, 5);
  const zeroChance = large ? 0.02 : rand() * 0.25;
  const negativeChance = rand();
  const cell = () => {
    if (rand() < zeroChance) return 0;
    const magnitude = large ? int(2, 4) : int(1, 4);
    return rand() < negativeChance ? -magnitude : magnitude;
  };
  return [Array.from({ length: rows }, () => Array.from({ length: cols }, cell))];
}
